<?php

namespace App\Services\Banking;

use App\Models\BankAccount;
use App\Models\User;
use Illuminate\Validation\ValidationException;

/**
 * Partner-bank rails.
 *
 * No NUBAN is ever generated by PayMef itself. Until a commercial bank signs
 * the partnership agreement the request is stored as pending; once a provider
 * is configured, issuance will happen in this service and nowhere else.
 */
class PartnerBankService
{
    public function forUser(User $user): ?BankAccount
    {
        return $user->bankAccounts()->latest('id')->first();
    }

    /**
     * @param  array<string, mixed>  $application
     */
    public function apply(User $requester, User $subject, array $application): BankAccount
    {
        $accountType = (string) ($application['account_type'] ?? 'student_savings');
        $currency = strtoupper((string) ($application['currency'] ?? 'NGN'));

        $existing = BankAccount::query()
            ->where('user_id', $subject->id)
            ->where('account_type', $accountType)
            ->where('currency', $currency)
            ->first();

        if ($existing !== null && $existing->isActive()) {
            throw ValidationException::withMessages([
                'account' => 'A partner bank account is already active for this profile.',
            ]);
        }

        $provider = (string) config('paymef.partner_bank.provider', 'none');
        $railsLive = $provider !== 'none' && $provider !== '';

        if ($railsLive) {
            // Provider integrations (Paystack DVA, bank BaaS) are added here.
            // They must return a real account number issued by the bank.
            $railsLive = false;
        }

        return BankAccount::updateOrCreate(
            [
                'user_id' => $subject->id,
                'account_type' => $accountType,
                'currency' => $currency,
            ],
            [
                'requested_by' => $requester->id,
                'provider' => $railsLive ? $provider : 'partner_bank',
                'account_number' => $railsLive ? ($existing?->account_number) : null,
                'account_name' => $subject->name,
                'bank_name' => null,
                'currency' => $currency,
                'status' => $railsLive ? 'pending' : 'pending_partner_bank_approval',
                'application' => $application,
                'failure_reason' => null,
                'metadata' => [
                    'bank_rails' => $railsLive ? 'pending_issuance' : 'awaiting_partner_approval',
                    'note' => 'Account numbers are issued only by the licensed partner bank.',
                ],
            ]
        )->refresh();
    }

    /**
     * @return array<string, mixed>
     */
    public function present(?BankAccount $account): ?array
    {
        if ($account === null) {
            return null;
        }

        $active = $account->isActive();

        return [
            'id' => $account->id,
            'status' => $account->status,
            'status_label' => match ($account->status) {
                'active' => 'Active',
                'pending' => 'Issuing with partner bank',
                'rejected' => 'Declined by partner bank',
                'suspended' => 'Suspended',
                default => 'Awaiting partner bank approval',
            },
            'provider' => $account->provider,
            'account_number' => $active ? $account->account_number : null,
            'account_name' => $active ? $account->account_name : null,
            'bank_name' => $active ? $account->bank_name : null,
            'bank_code' => $active ? $account->bank_code : null,
            'currency' => $account->currency,
            'account_type' => $account->account_type,
            'is_active' => $active,
            'requested_at' => $account->created_at?->toIso8601String(),
            'approved_at' => $account->approved_at?->toIso8601String(),
            'message' => $active
                ? 'Dedicated account issued by the licensed partner bank.'
                : 'Your account request is recorded. A dedicated NUBAN is issued once the partner bank approves PayMef\'s integration.',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function capabilities(): array
    {
        return [
            'partner_bank_rails' => 'awaiting_partner_approval',
            'bank_rails_message' => 'Virtual account issuance and bank-to-wallet transfers activate once the partner bank integration is approved.',
            'provider' => (string) config('paymef.partner_bank.provider', 'none'),
        ];
    }
}
